// ⭐ D105 P4 · ADMIN → DATA → ATLAS — the curator's minimal list, so the owner can publish the first pages.
//
// Every node is seeded as a DRAFT (D17: nothing generated by a model) and a public reader sees PUBLISHED pages only,
// so until someone publishes, /atlas is empty. This panel lists the nodes (drafts first by default), sorted by how
// many active postings ask for each — D105's first published set is "the roles the board has most postings for, then
// their top 20 skills each" — with Publish / Unpublish per row and "Recompute On the board".
//   GET  /api/admin/atlas?status=draft|published     POST /api/admin/atlas/:slug/status { status }
//   POST /api/admin/atlas/stats
// ⭐ D105 P6 · THE EDITOR (routes/atlas.js, admin only): Add a node (kind, name, a definition in draft's words — D17, no
// model), Merge two (the loser's edges and resources move; its term becomes a CONFIRMED alias in skill_synonyms, the one
// thesaurus), and per node: the definition and Wikipedia title, typed edges (never alias_of), resources (https only,
// title, level, format, hours, cost), "Check links now" (the daily dead-link checker) and "Refresh Wikipedia".
// ⭐ D105 P7 (amended 10-31) · THE ATLAS PUBLISHES ITSELF: a draft is published nightly once ≥ 5 active postings ask for
// it AND it has a Wikipedia summary or a definition. Each draft row says why it is not published yet (readinessLine:
// "postings 2 of 5 · no Wikipedia summary or definition"), a node a person unpublished says so and stays a draft, and
// "Run auto-publish now" runs the nightly titles → Wikidata → Wikipedia → bar pass (POST /api/admin/atlas/auto/run).
import { useCallback, useEffect, useMemo, useState } from "react";
import { api } from "../lib/api.js";
import { C } from "../styles/colorTokens.js";
import DepthButton from "../components/DepthButton.jsx";
import { FAMILIES } from "../../../shared/atlasFamilies.js";
import { Panel, Mark, row, quiet, sub, callout, field, useConfirm } from "./adminKit.jsx";
// ⭐ D118 P2 · Import content — the Learn content replaced from the owner's tracker, no deploy (adminLearnImport.jsx).
import { AtlasImportContent } from "./adminLearnImport.jsx";
// ⭐ D117 C9 · Learn → Before-this review — the drafted links accepted, edited or rejected; P5's held links; the routes.
import { LearnBeforeThisReview, LearnThumbnails } from "./adminLearnCircle.jsx";

const KINDS = [["", "All kinds"], ["role", "Roles"], ["skill", "Skills"], ["tool", "Tools"], ["stack", "Stacks"], ["concept", "Concepts"], ["pattern", "Patterns"]];
const NODE_KINDS = ["role", "skill", "tool", "stack", "concept", "pattern"];
const EDGE_TYPES = [["requires", "requires"], ["part_of", "part of"], ["used_with", "used with"], ["alternative_to", "alternative to"], ["leads_to", "leads to"]];
const LEVELS = ["", "beginner", "intermediate", "advanced"];
const FORMATS = ["", "course", "docs", "book", "video", "tutorial", "article", "practice"];
const COSTS = ["", "free", "freemium", "paid"];
const STATUS_TONE = { ok: C.SUCCESS, failing: C.WARNING, dead: C.DANGER };
const enc = encodeURIComponent;
const send = (path, body, method = "POST") => api(path, { method, body: JSON.stringify(body || {}) });
const label = { display: "flex", flexDirection: "column", gap: 3, fontSize: 11, color: C.INK_MUTED };

/** Why a row is (not) published — from the server's readiness (services/atlas/atlasPublish.js readiness). */
function readinessLine(r) {
  const rd = r?.readiness;
  if (!rd) return null;
  if (r.status === "published") {
    const auto = r.publishedBy === "atlas-auto" ? "published automatically" : r.publishedBy ? `published by ${r.publishedBy}` : "published";
    return rd.postings < rd.need ? `${auto} · few open postings (${rd.postings} of ${rd.need}) — stays published` : auto;
  }
  if (rd.heldBy) return `unpublished by ${rd.heldBy} — auto-publish leaves it a draft until someone publishes it`;
  if (rd.ready) return "meets the bar — published at the next nightly check (or Run auto-publish now)";
  return `not published yet: ${rd.missing.join(" · ")}`;
}

// ⭐ BUG 10-31 · what Wikipedia's last answer was for each node, counted (GET /api/admin/atlas/wiki/classes), with the
// nodes under each — the list the owner picks titles from — and "Show a real answer" (GET …/wiki/probe): one
// Wikipedia + Wikidata answer exactly as this server receives it, to copy into the chat.
const MATCH_WORDS = [["matched", "Matched"], ["missing", "No such article"], ["not_in_answer", "Not in the answer"],
  ["disambiguation", "Disambiguation page"], ["inexact", "Redirects to another name"], ["not_software", "Not software (tool)"], ["no_item", "No Wikidata item"]];
// ⭐ D105 P10 · FIND ON WIKIPEDIA — per unmatched node, the candidates its class calls for (GET …/node/:slug/wiki-candidates),
// each with Wikipedia's first sentence; one press stores the title and the Wikidata ID (POST …/wiki-pick). A tool that
// is "not software" on Wikidata gets "Use it anyway"; a node with no article points at a definition (P11).
function AtlasWikiFind({ node, say, onPicked }) {
  const [found, setFound] = useState(null);
  const [busy, setBusy] = useState(false);
  const find = async () => {
    setBusy(true);
    try { setFound(await api(`/api/admin/atlas/node/${enc(node.slug)}/wiki-candidates`)); } catch (e) { say({ ok: false, text: e.message }); }
    finally { setBusy(false); }
  };
  const pick = async (c) => {
    setBusy(true);
    try {
      await send(`/api/admin/atlas/node/${enc(node.slug)}/wiki-pick`, { title: c.title, wikidataId: c.item });
      say({ ok: true, text: `${node.name} → “${c.title}”. Its summary is read on the next run (or Refresh Wikipedia).` });
      onPicked();
    } catch (e) { say({ ok: false, text: e.message }); }
    finally { setBusy(false); }
  };
  return (
    <div data-atlas-find={node.slug} style={{ fontSize: 12, color: C.INK }}>
      <span>{node.name} <span style={quiet}>({node.kind})</span></span>{" "}
      {!found && <DepthButton size="compact" disabled={busy} onClick={find} data-atlas-find-open={node.slug}>Find on Wikipedia</DepthButton>}
      {found && (
        <div style={{ display: "grid", gap: 4, margin: "4px 0 8px 12px" }}>
          {found.candidates.map(c => (
            <div key={c.title} style={{ ...row, alignItems: "flex-start" }}>
              <DepthButton size="compact" disabled={busy} onClick={() => pick(c)} data-atlas-pick={c.title}>{c.useAnyway ? "Use it anyway" : "Use this"}</DepthButton>
              <span style={{ flex: "1 1 220px", overflowWrap: "anywhere" }}><b>{c.title}</b>{c.extract ? ` — ${c.extract}` : ""} <span style={quiet}>From Wikipedia</span></span>
            </div>
          ))}
          {found.writeDefinition && <span style={quiet}>No article fits? Write a definition — Edit, or Draft definitions.</span>}
        </div>
      )}
    </div>
  );
}

// Redirects alone may be accepted as a group, after reading the preview (GET …/wiki/redirects → POST …/accept).
function AtlasRedirectGroup({ say, onPicked }) {
  const [list, setList] = useState(null);
  const [busy, setBusy] = useState(false);
  const preview = async () => {
    setBusy(true);
    try { setList((await api("/api/admin/atlas/wiki/redirects")).redirects); } catch (e) { say({ ok: false, text: e.message }); }
    finally { setBusy(false); }
  };
  const ready = (list || []).filter(r => r.title);
  const acceptAll = async () => {
    setBusy(true);
    try {
      const r = await send("/api/admin/atlas/wiki/redirects/accept", { picks: ready.map(x => ({ slug: x.slug, title: x.title, wikidataId: x.item })) });
      say({ ok: true, text: `${r.picked.length} redirect(s) accepted — summaries on the next run.` }); setList(null); onPicked();
    } catch (e) { say({ ok: false, text: e.message }); }
    finally { setBusy(false); }
  };
  if (!list) return <DepthButton size="compact" disabled={busy} onClick={preview} data-atlas-redirect-preview="">Preview every redirect</DepthButton>;
  return (
    <div data-atlas-redirect-list="" style={{ display: "grid", gap: 3, fontSize: 12, color: C.INK }}>
      {list.map(r => <span key={r.slug} style={{ overflowWrap: "anywhere" }}>{r.name} → {r.title ? <b>{r.title}</b> : <span style={quiet}>no target</span>}{r.extract ? ` — ${r.extract}` : ""}</span>)}
      <div style={row}>
        <DepthButton size="compact" primary disabled={busy || !ready.length} onClick={acceptAll} data-atlas-redirect-accept="">Accept all {ready.length}</DepthButton>
        <DepthButton size="compact" disabled={busy} onClick={() => setList(null)}>Close</DepthButton>
      </div>
    </div>
  );
}

// ⭐ D105 P11 · DRAFT DEFINITIONS — the Admin → Enrichment pattern: copy the export into a Claude chat, paste its JSON
// answer back; each lands as a DRAFT (never public, never counted by the bar) for Accept · Edit · Reject, or Accept all
// after reading. draft makes no model call (D17).
function AtlasDraftDefinitions({ say, onChanged }) {
  const [out, setOut] = useState(null);
  const [answer, setAnswer] = useState("");
  const [errors, setErrors] = useState(null);
  const [drafts, setDrafts] = useState(null);
  const [edits, setEdits] = useState({});
  const [busy, setBusy] = useState(false);
  const [recent, setRecent] = useState(null);
  const [spot, setSpot] = useState(null);
  const loadDrafts = useCallback(() => {
    api("/api/admin/atlas/definitions/drafts").then(r => setDrafts(r.drafts)).catch(() => setDrafts([]));
    api("/api/admin/atlas/definitions/recent").then(r => setRecent(r.recent)).catch(() => setRecent([]));
  }, []);
  useEffect(() => { loadDrafts(); }, [loadDrafts]);
  const unpublish = (d) => act(async () => { await send(`/api/admin/atlas/definitions/${enc(d.slug)}/unpublish`); say({ ok: true, text: `${d.name}: unpublished.` }); loadDrafts(); onChanged(); });
  const spotCheck = () => act(async () => setSpot(await api("/api/admin/atlas/definitions/spot-check")));
  const act = async (fn) => { setBusy(true); try { await fn(); } catch (e) { say({ ok: false, text: e.message }); } finally { setBusy(false); } };
  const exportNow = () => act(async () => setOut(await api("/api/admin/atlas/definitions/export")));
  const copy = () => { try { navigator.clipboard?.writeText(out.text); say({ ok: true, text: `Copied ${out.nodes.length} item(s) — paste them into a Claude chat.` }); } catch { /* select it by hand */ } };
  const importNow = () => act(async () => {
    setErrors(null);
    let r;
    try { r = await send("/api/admin/atlas/definitions/import", { text: answer }); }
    catch (e) { if (e.status === 400) { setErrors(e.payload?.errors || [{ slug: null, reason: "refused" }]); return; } throw e; }
    say({ ok: true, text: `${r.published} definition(s) published${r.drafted ? ` · ${r.drafted} held as drafts (their source)` : ""}.` }); setAnswer(""); setOut(null); loadDrafts(); onChanged();
  });
  const accept = (d) => act(async () => {
    const r = await send(`/api/admin/atlas/definitions/${enc(d.slug)}/accept`, edits[d.slug] != null ? { definition: edits[d.slug] } : {});
    say({ ok: true, text: `${d.name}: accepted${r.published?.length ? ` — published ${r.published.join(", ")}` : ""}.` }); loadDrafts(); onChanged();
  });
  const reject = (d) => act(async () => { await send(`/api/admin/atlas/definitions/${enc(d.slug)}/reject`); loadDrafts(); });
  const acceptAll = () => act(async () => {
    const r = await send("/api/admin/atlas/definitions/accept-all", { slugs: drafts.filter(d => edits[d.slug] == null).map(d => d.slug) });
    say({ ok: true, text: `${r.accepted} accepted as written${r.published.length ? ` — published ${r.published.length}` : ""}. Edited ones wait for their own Accept.` }); loadDrafts(); onChanged();
  });
  return (
    <div data-atlas-definitions="" style={{ ...sub, marginBottom: 12, display: "grid", gap: 8 }}>
      <div style={{ ...row, justifyContent: "space-between" }}>
        <b style={{ fontSize: 13, color: C.INK }}>Draft definitions</b>
        <DepthButton size="compact" disabled={busy} onClick={exportNow} data-atlas-def-export="">Draft definitions</DepthButton>
      </div>
      {out && (
        <div style={{ display: "grid", gap: 6 }}>
          <span style={quiet}>1. Copy this into a Claude chat. 2. Paste its JSON answer below. Definitions that pass the rules publish at once; unpublish any from the list below.</span>
          <textarea readOnly value={out.text} rows={6} style={{ ...field, fontFamily: "monospace", fontSize: 11 }} aria-label="Items to define" />
          <div style={row}><DepthButton size="compact" onClick={copy} data-atlas-def-copy="">Copy</DepthButton></div>
          <textarea value={answer} onChange={e => setAnswer(e.target.value)} rows={5} placeholder='{ "definitions": [ … ] }' style={{ ...field, fontFamily: "monospace", fontSize: 11 }} aria-label="The chat's answer" />
          <div style={row}><DepthButton size="compact" primary disabled={busy || !answer.trim()} onClick={importNow} data-atlas-def-import="">Import and publish</DepthButton></div>
          {errors && <div style={callout(C.DANGER)}>Refused — nothing was saved: {errors.map(e => `${e.slug || "file"}: ${e.reason}`).join(" · ")}</div>}
        </div>
      )}
      {drafts?.length > 0 && (
        <div data-atlas-def-review="" style={{ display: "grid", gap: 6 }}>
          {drafts.map(d => (
            <div key={d.slug} style={{ display: "grid", gap: 4 }}>
              <span style={{ fontSize: 12, color: C.INK }}><b>{d.name}</b> <span style={quiet}>{d.kind} · {d.postings} posting(s) · drafted</span></span>
              <textarea value={edits[d.slug] ?? d.draft} onChange={e => setEdits(x => ({ ...x, [d.slug]: e.target.value }))} rows={2} style={{ ...field, fontSize: 12 }} aria-label={`Definition of ${d.name}`} />
              <div style={row}>
                <DepthButton size="compact" primary disabled={busy} onClick={() => accept(d)} data-atlas-def-accept={d.slug}>Accept</DepthButton>
                <DepthButton size="compact" disabled={busy} onClick={() => reject(d)} data-atlas-def-reject={d.slug}>Reject</DepthButton>
              </div>
            </div>
          ))}
          <div style={row}><DepthButton size="compact" disabled={busy} onClick={acceptAll} data-atlas-def-accept-all="">Accept all as written</DepthButton></div>
        </div>
      )}
      <div data-atlas-def-recent="" style={{ display: "grid", gap: 6 }}>
        <div style={{ ...row, justifyContent: "space-between" }}>
          <b style={{ fontSize: 12, color: C.INK }}>Recently published</b>
          <DepthButton size="compact" disabled={busy} onClick={spotCheck} data-atlas-def-spot="">This week's spot-check (10)</DepthButton>
        </div>
        {spot && <div style={quiet} data-atlas-def-spot-list="">Week {spot.week}: {spot.items.length ? spot.items.map(i => i.name).join(" · ") : "nothing published yet"}</div>}
        {recent?.length === 0 && <span style={quiet}>Nothing published automatically yet.</span>}
        {(recent || []).map(d => (
          <div key={d.slug} style={{ ...row, alignItems: "flex-start" }}>
            <span style={{ fontSize: 12, color: C.INK, flex: 1 }}><b>{d.name}</b> <span style={quiet}>{d.kind} · {d.postings} posting(s)</span> — {d.definition}</span>
            <DepthButton size="compact" disabled={busy} onClick={() => unpublish(d)} data-atlas-def-unpublish={d.slug}>Unpublish</DepthButton>
          </div>
        ))}
      </div>
    </div>
  );
}

function AtlasWikiAnswers({ reloadKey, say }) {
  const [sum, setSum] = useState(null);
  const [probe, setProbe] = useState(null);
  const [busy, setBusy] = useState(false);
  const [again, setAgain] = useState(0);
  useEffect(() => { api("/api/admin/atlas/wiki/classes").then(setSum).catch(() => setSum(null)); }, [reloadKey, again]);
  const picked = () => setAgain(n => n + 1);
  const runProbe = async () => {
    setBusy(true); setProbe(null);
    try { setProbe(await api("/api/admin/atlas/wiki/probe")); } catch (e) { say({ ok: false, text: e.message }); }
    finally { setBusy(false); }
  };
  return (
    <div data-atlas-wiki-answers="" style={{ ...sub, marginBottom: 12 }}>
      <div style={{ ...row, justifyContent: "space-between" }}>
        <b style={{ fontSize: 13, color: C.INK }}>Wikipedia's last answer, per node</b>
        <DepthButton size="compact" disabled={busy} onClick={runProbe} data-atlas-probe="">Show a real answer</DepthButton>
      </div>
      {!sum ? <p style={quiet}>No answers yet.</p> : (
        <div style={{ display: "grid", gap: 4, marginTop: 6 }}>
          {MATCH_WORDS.map(([c, l]) => (
            <details key={c} data-atlas-class={c}>
              <summary style={{ fontSize: 12, color: C.INK, cursor: "pointer" }}>{l}: <b>{sum.counts?.[c] ?? 0}</b></summary>
              {c === "matched" ? <p style={{ ...quiet, overflowWrap: "anywhere" }}>{(sum.nodes?.[c] || []).map(n => `${n.name} (${n.kind})`).join(" · ") || "—"}</p> : (
                <div style={{ display: "grid", gap: 4, margin: "4px 0 6px" }}>
                  {c === "inexact" && (sum.counts?.[c] ?? 0) > 0 && <AtlasRedirectGroup say={say} onPicked={picked} />}
                  {(sum.nodes?.[c] || []).map(n => <AtlasWikiFind key={n.slug} node={n} say={say} onPicked={picked} />)}
                  {!(sum.nodes?.[c] || []).length && <span style={quiet}>—</span>}
                </div>
              )}
            </details>
          ))}
          <span style={quiet}>{sum.neverAnswered} node(s) never answered.</span>
        </div>
      )}
      {probe && (
        <pre data-atlas-probe-out="" style={{ fontSize: 11, maxHeight: 320, overflow: "auto", whiteSpace: "pre-wrap", overflowWrap: "anywhere", color: C.INK }}>
          {JSON.stringify(probe, null, 1)}
        </pre>
      )}
    </div>
  );
}

/** Add a node by hand — a DRAFT until it is published. */
function AtlasAddNode({ onAdded, say }) {
  const [kind, setKind] = useState("skill");
  const [name, setName] = useState("");
  const [definition, setDefinition] = useState("");
  const [busy, setBusy] = useState(false);
  const add = async () => {
    setBusy(true);
    try {
      const r = await send("/api/admin/atlas/nodes", { kind, name, definition });
      say({ ok: true, text: `${r.node.name} added as a draft (/atlas/${r.node.slug} once published).` });
      setName(""); setDefinition(""); onAdded?.(r.node);
    } catch (e) { say({ ok: false, text: e.message }); }
    finally { setBusy(false); }
  };
  return (
    <div data-atlas-add="" style={{ ...sub, display: "grid", gap: 8 }}>
      <b style={{ fontSize: 13, color: C.INK }}>Add a node</b>
      <div style={row}>
        <select aria-label="New node's kind" value={kind} onChange={e => setKind(e.target.value)} style={field}>
          {NODE_KINDS.map(k => <option key={k} value={k}>{k}</option>)}
        </select>
        <input aria-label="New node's name" placeholder="Name (e.g. Kubernetes)" value={name} onChange={e => setName(e.target.value)} style={{ ...field, flex: "1 1 200px" }} />
      </div>
      <textarea aria-label="New node's definition" rows={2} placeholder="Definition — in draft's own words" value={definition}
        onChange={e => setDefinition(e.target.value)} style={{ ...field, height: "auto", padding: 8 }} />
      <div><DepthButton size="compact" primary disabled={busy || !name.trim()} onClick={add} data-atlas-add-go="">Add as a draft</DepthButton></div>
    </div>
  );
}

/** Merge two nodes: the loser's edges, resources and term move to the winner (its term a confirmed alias). */
function AtlasMerge({ onMerged, say }) {
  const [winner, setWinner] = useState("");
  const [loser, setLoser] = useState("");
  const [busy, setBusy] = useState(false);
  const { ask, dialog } = useConfirm();
  const merge = async () => {
    const ok = await ask({ title: "Merge two Atlas nodes", label: "Merge",
      body: <p style={{ margin: 0 }}><b>{loser}</b> is deleted. Its edges and resources move to <b>{winner}</b>, and its term becomes a confirmed alias of it in the scorer's thesaurus — which changes ATS scores (re-measure ρ after a batch, A76).</p> });
    if (!ok) return;
    setBusy(true);
    try {
      const r = await send("/api/admin/atlas/merge", { winner: winner.trim(), loser: loser.trim() });
      say({ ok: true, text: `Merged ${r.loser} into ${r.winner}: ${r.edgesMoved} edge(s), ${r.resourcesMoved} resource(s) moved; alias ${r.aliases.join(", ") || "—"}.` });
      setLoser(""); onMerged?.(r);
    } catch (e) { say({ ok: false, text: e.message }); }
    finally { setBusy(false); }
  };
  return (
    <div data-atlas-merge="" style={{ ...sub, display: "grid", gap: 8 }}>
      <b style={{ fontSize: 13, color: C.INK }}>Merge two nodes</b>
      <div style={row}>
        <input aria-label="Keep this node (slug)" placeholder="Keep (slug, e.g. kubernetes)" value={winner} onChange={e => setWinner(e.target.value)} style={{ ...field, flex: "1 1 160px" }} />
        <input aria-label="Merge this node into it (slug)" placeholder="Merge in and delete (slug, e.g. k8s)" value={loser} onChange={e => setLoser(e.target.value)} style={{ ...field, flex: "1 1 160px" }} />
        <DepthButton size="compact" disabled={busy || !winner.trim() || !loser.trim() || winner.trim() === loser.trim()} onClick={merge} data-atlas-merge-go="">Merge</DepthButton>
      </div>
      {dialog}
    </div>
  );
}

const blankResource = { url: "", title: "", level: "", format: "", hours: "", cost: "" };

/** One resource's fields — for a new one and for an edit. */
function AtlasResourceFields({ value, onChange }) {
  const set = (k) => (e) => onChange({ ...value, [k]: e.target.value });
  const pick = (k, list) => (
    <label style={label}>{k}
      <select value={value[k] ?? ""} onChange={set(k)} style={field}>{list.map(v => <option key={v} value={v}>{v || "—"}</option>)}</select>
    </label>
  );
  return (
    <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(130px, 1fr))", gap: 8 }}>
      <label style={{ ...label, gridColumn: "1 / -1" }}>Address (https only)<input type="url" value={value.url} onChange={set("url")} style={field} placeholder="https://…" /></label>
      <label style={{ ...label, gridColumn: "1 / -1" }}>Title<input value={value.title} onChange={set("title")} style={field} /></label>
      {pick("level", LEVELS)}{pick("format", FORMATS)}{pick("cost", COSTS)}
      <label style={label}>hours<input type="number" min="0" step="0.5" value={value.hours ?? ""} onChange={set("hours")} style={field} /></label>
    </div>
  );
}

/** The editor for one node: definition + Wikipedia title, typed edges, resources. */
function AtlasNodeEditor({ slug, say }) {
  const [n, setN] = useState(null);
  const [definition, setDefinition] = useState("");
  const [wikiTitle, setWikiTitle] = useState("");
  const [family, setFamily] = useState("");   // ⭐ D116 M1: "" = none (not drawn on the tree)
  const [edge, setEdge] = useState({ to: "", type: "requires" });
  const [res, setRes] = useState(blankResource);
  const [editing, setEditing] = useState(null);   // { id, ...fields }
  const [busy, setBusy] = useState(false);
  const load = useCallback(() => api(`/api/admin/atlas/node/${enc(slug)}`).then(d => {
    setN(d); setDefinition(d.definition || ""); setWikiTitle(d.wikiTitle || ""); setFamily(d.family || "");
  }).catch(e => say({ ok: false, text: e.message })), [slug, say]);
  useEffect(() => { load(); }, [load]);
  const run = async (fn, okText) => {
    setBusy(true);
    try { await fn(); if (okText) say({ ok: true, text: okText }); await load(); }
    catch (e) { say({ ok: false, text: e.message }); }
    finally { setBusy(false); }
  };
  if (!n) return <p style={quiet}>Loading…</p>;
  const toFields = (r) => ({ id: r.id, url: r.url, title: r.title, level: r.level || "", format: r.format || "", hours: r.hours ?? "", cost: r.cost || "" });
  const removeEdge = (e) => (e.dir === "out"
    ? api(`/api/admin/atlas/node/${enc(slug)}/edges?to=${enc(e.slug)}&type=${enc(e.type)}`, { method: "DELETE" })
    : api(`/api/admin/atlas/node/${enc(e.slug)}/edges?to=${enc(slug)}&type=${enc(e.type)}`, { method: "DELETE" }));
  return (
    <div data-atlas-editor={slug} style={{ display: "grid", gap: 12, marginTop: 8, width: "100%" }}>
      <div style={{ display: "grid", gap: 6 }}>
        <label style={label}>Definition — in draft's own words (never Wikipedia's, never a model's)
          <textarea rows={3} value={definition} onChange={e => setDefinition(e.target.value)} style={{ ...field, height: "auto", padding: 8 }} data-atlas-definition="" />
        </label>
        <label style={label}>Wikipedia article title (its summary is shown as Wikipedia's, refreshed weekly; empty = none)
          <input value={wikiTitle} onChange={e => setWikiTitle(e.target.value)} style={field} placeholder="e.g. Kubernetes" data-atlas-wiki-title="" />
        </label>
        <label style={label}>Family on Your map's tree (D116 — set once; the seed never overrides your choice{n.familyBy ? `, set by ${n.familyBy}` : ""})
          <select value={family} onChange={e => setFamily(e.target.value)} style={field} data-atlas-family="">
            <option value="">None — not drawn on the tree</option>
            {FAMILIES.map(f => <option key={f.key} value={f.key}>{f.name}</option>)}
          </select>
        </label>
        <div><DepthButton size="compact" primary disabled={busy} data-atlas-save=""
          onClick={() => run(() => send(`/api/admin/atlas/node/${enc(slug)}`, { definition, wikiTitle, ...(family !== (n.family || "") ? { family } : {}) }, "PATCH"), `${n.name} saved.`)}>Save</DepthButton></div>
        {n.aliases?.length > 0 && <span style={quiet}>Aliases (skill_synonyms, confirmed): {n.aliases.join(", ")}</span>}
      </div>

      <div data-atlas-edges="" style={{ display: "grid", gap: 6 }}>
        <b style={{ fontSize: 12, color: C.INK }}>Edges</b>
        {n.edges.length === 0 && <span style={quiet}>None yet.</span>}
        {n.edges.map(e => (
          <div key={`${e.dir}:${e.type}:${e.slug}`} style={row}>
            <span style={{ fontSize: 12, color: C.INK, flex: "1 1 220px", overflowWrap: "anywhere" }}>
              {e.dir === "out" ? <>{n.name} <i>{e.type.replace(/_/g, " ")}</i> <b>{e.name}</b></> : <><b>{e.name}</b> <i>{e.type.replace(/_/g, " ")}</i> {n.name}</>}
              <span style={quiet}> · {e.source}{e.status !== "published" ? " · draft" : ""}</span>
            </span>
            <DepthButton size="compact" disabled={busy} data-atlas-edge-remove="" onClick={() => run(() => removeEdge(e), "Edge removed.")}>Remove</DepthButton>
          </div>
        ))}
        <div style={row}>
          <span style={{ fontSize: 12, color: C.INK_MUTED }}>{n.name}</span>
          <select aria-label="Edge type" value={edge.type} onChange={e => setEdge({ ...edge, type: e.target.value })} style={field}>
            {EDGE_TYPES.map(([v, l]) => <option key={v} value={v}>{l}</option>)}
          </select>
          <input aria-label="Edge target (slug)" placeholder="slug, e.g. docker" value={edge.to} onChange={e => setEdge({ ...edge, to: e.target.value })} style={{ ...field, flex: "1 1 140px" }} />
          <DepthButton size="compact" disabled={busy || !edge.to.trim()} data-atlas-edge-add=""
            onClick={() => run(async () => { await send(`/api/admin/atlas/node/${enc(slug)}/edges`, { to: edge.to.trim(), type: edge.type }); setEdge({ ...edge, to: "" }); }, "Edge added.")}>Add edge</DepthButton>
        </div>
      </div>

      <div data-atlas-resources="" style={{ display: "grid", gap: 8 }}>
        <b style={{ fontSize: 12, color: C.INK }}>Resources</b>
        {n.resources.length === 0 && <span style={quiet}>None yet.</span>}
        {n.resources.map(r => editing?.id === r.id ? (
          <div key={r.id} style={{ ...sub, display: "grid", gap: 8 }}>
            <AtlasResourceFields value={editing} onChange={setEditing} />
            <div style={row}>
              <DepthButton size="compact" primary disabled={busy} data-atlas-resource-save=""
                onClick={() => run(async () => { const { id, ...body } = editing; await send(`/api/admin/atlas/resources/${id}`, body, "PATCH"); setEditing(null); }, "Resource saved.")}>Save</DepthButton>
              <DepthButton size="compact" onClick={() => setEditing(null)}>Cancel</DepthButton>
            </div>
          </div>
        ) : (
          <div key={r.id} style={row} data-atlas-resource={r.id}>
            <span style={{ fontSize: 12, color: C.INK, flex: "1 1 220px", overflowWrap: "anywhere" }}>
              <a href={r.url} target="_blank" rel="noopener noreferrer" style={{ color: C.ACCENT_INK }}>{r.title}</a>
              <span style={quiet}> · {[r.level, r.format, r.hours != null ? `${r.hours} h` : null, r.cost].filter(Boolean).join(" · ") || "—"}</span>
            </span>
            {r.checkStatus && <Mark tone={STATUS_TONE[r.checkStatus] || C.INK_MUTED}>{r.checkStatus === "dead" ? "dead — hidden" : r.checkStatus}</Mark>}
            <DepthButton size="compact" disabled={busy} onClick={() => setEditing(toFields(r))} data-atlas-resource-edit="">Edit</DepthButton>
            <DepthButton size="compact" disabled={busy} data-atlas-resource-remove=""
              onClick={() => run(() => api(`/api/admin/atlas/resources/${r.id}`, { method: "DELETE" }), "Resource removed.")}>Remove</DepthButton>
          </div>
        ))}
        <div style={{ ...sub, display: "grid", gap: 8 }}>
          <AtlasResourceFields value={res} onChange={setRes} />
          <div><DepthButton size="compact" disabled={busy || !res.url.trim() || !res.title.trim()} data-atlas-resource-add=""
            onClick={() => run(async () => { await send(`/api/admin/atlas/node/${enc(slug)}/resources`, res); setRes(blankResource); }, "Resource added.")}>Add resource</DepthButton></div>
        </div>
      </div>
    </div>
  );
}

// ⛔ D176 · SOURCES — the learning-centre register (content/sources/registry.json, services/atlas/sourceRegistry.js):
// how many sources per licence class, per pathway (and how many are vendor-neutral — "no lesson draws on a single
// vendor"), which licences are still to be read (link-only until then), and the monthly link check's dead links.
//   GET /api/admin/atlas/sources        POST /api/admin/atlas/sources/check (the link check, now)
function AtlasSources({ say }) {
  const [s, setS] = useState(null);
  const [busy, setBusy] = useState(false);
  const load = useCallback(() => { api("/api/admin/atlas/sources").then(setS).catch(e => say({ ok: false, text: e.message })); }, [say]);
  useEffect(() => { load(); }, [load]);
  const check = async () => {
    setBusy(true);
    try {
      const r = await api("/api/admin/atlas/sources/check", { method: "POST" });
      say({ ok: r.dead.length === 0, text: `Sources checked: ${r.checked} — ${r.dead.length ? `dead: ${r.dead.join(", ")}` : "every link answered"}.` });
      load();
    } catch (e) { say({ ok: false, text: e.message }); }
    setBusy(false);
  };
  if (!s) return null;
  const dead = (s.links?.results || []).filter(r => !r.ok);
  return (
    <Panel title="Sources" data-admin-atlas-sources=""
      code="D176: content/sources/registry.json — one row per learning centre; its licence class decides whether text may be adapted (open-reuse, share-alike) or only summarised and linked."
      purpose="Where Atlas's lessons may draw from, and on what terms. A source still 'to verify' is link-only until its licence is read."
      numbers={[[String(s.total), "sources"], [String(s.byClass["open-reuse"] + s.byClass["share-alike"]), "may be adapted, with credit"],
        [String(s.toVerify.length), "licences still to read", s.toVerify.length > 0], [String(dead.length), "dead links", dead.length > 0]]}>
      {!s.validation.ok && <div style={{ ...callout(C.DANGER), marginBottom: 8 }}>The register has problems: {s.validation.problems.join(" · ")}</div>}
      <div style={quiet}>
        {Object.entries(s.byPathway).sort((a, b) => b[1].sources - a[1].sources)
          .map(([p, b]) => `${p} ${b.sources}${b.neutral ? "" : " (no neutral source)"}`).join(" · ")}
      </div>
      {s.toVerify.length > 0 && <div style={quiet}>To verify ({s.toVerify.length}): {s.toVerify.slice(0, 30).join(", ")}{s.toVerify.length > 30 ? ` and ${s.toVerify.length - 30} more` : ""}</div>}
      {/* D176-3: every Learn item's source, resolved from this register against the content Learn serves. */}
      {s.learn && (<div style={quiet} data-atlas-sources-learn="">
        Learn items: {s.learn.resolved} of {s.learn.items} have a registered source ({s.learn.own} are draft's own tasks)
        {s.learn.needsNamedSource.length > 0 && <> · {s.learn.needsNamedSource.length} link to a search, not a named source — replace each: {s.learn.needsNamedSource.slice(0, 12).map(x => `${x.stepId} ${x.title}`).join(" · ")}{s.learn.needsNamedSource.length > 12 ? " …" : ""}</>}
        {s.learn.unregistered.length > 0 && <> · {s.learn.unregistered.length} name a source the register doesn't have</>}
      </div>)}
      {s.aiRestricted?.length > 0 && <div style={quiet} data-atlas-sources-ai="">Never sent to a model (their AI terms): {s.aiRestricted.join(", ")}</div>}
      {dead.length > 0 && <div style={quiet}>Dead at the last check: {dead.map(d => `${d.id} (${d.status ?? d.error})`).join(", ")}</div>}
      <div style={{ ...row, marginTop: 8 }}>
        <DepthButton size="compact" disabled={busy} onClick={check} data-atlas-sources-check="">Check sources now</DepthButton>
        <span style={quiet}>{s.links?.at ? `last checked ${new Date(s.links.at * 1000).toISOString().slice(0, 10)}` : "not checked yet"} · monthly</span>
      </div>
    </Panel>
  );
}

// ⭐ D185-3 (45q) · RISING SKILLS → THE CONTENT BACKLOG. What the market is starting to ask for, by role, ranked up where
// Atlas has no lesson and where people hold the skill; "Draft an outline" writes a brief (steps + the register's sources,
// adapt or link-only) as a DRAFT for review here. Nothing is published from this panel — lessons are built in the editor.
// ⭐ A154 / D172 (4) (45s, owner 11-08: "build league and challenges, can merge them later") · the three Compete switches —
// each OFF until the owner turns it on; while off, its routes answer 404 and Atlas draws nothing of it. Audited.
const COMPETE_SWITCHES = [["league", "This week's league", "opt-in pods by school and field, handles only, the pod's rank on Your run"],
  ["challenges", "Challenges", "Beat the bar (a kept audit's score as a link), Time attack, the Friday duel (needs the league)"],
  ["liveCount", "Live count", `"N people practising <field> right now" on Your run — a real count, shown only at 10 or more`]];
export function AtlasCompeteSection() {
  const [s, setS] = useState(null);
  const [err, setErr] = useState(null);
  const load = useCallback(() => { api("/api/admin/atlas-compete").then(setS).catch(e => setErr(e.message)); }, []);
  useEffect(() => { load(); }, [load]);
  const { ask, dialog } = useConfirm();
  const flip = async (k, on) => {
    if (on && !(await ask({ title: "Turn this on for everyone?", label: "Turn on", body: "Everyone signed in will see it in Atlas." }))) return;
    try { setS(await api("/api/admin/atlas-compete", { method: "PUT", body: JSON.stringify({ [k]: on }) })); } catch (e) { setErr(e.message); }
  };
  return (
    <Panel title="Compete — league, challenges, live count" data-admin-atlas-compete=""
      code="A154: services/atlas/league.js + challenges.js, routes/atlasCompete.js; league_members / challenge_runs (migration 264)."
      purpose="Each switch is OFF until you turn it on. Points stay proof-only; challenges earn none."
      numbers={s?.counts ? [[String(s.counts.members ?? 0), "in the league"], [String(s.counts.pods ?? 0), "pods"], [String(s.counts.challengesFinished ?? 0), "challenges finished"], [String(s.counts.barsShared ?? 0), "scores shared"]] : []}>
      {dialog}
      {err && <div style={callout}>{err}</div>}
      <div style={{ display: "grid", gap: 8 }}>
        {COMPETE_SWITCHES.map(([k, label, what]) => (
          <div key={k} style={row} data-compete-switch={k} data-compete-state={s?.[k] ? "on" : "off"}>
            <b>{label}</b> <span style={quiet}>{what}</span>
            <span><b>{s ? (s[k] ? "On" : "Off") : "…"}</b></span>
            {s && <DepthButton primary={!s[k]} onClick={() => flip(k, !s[k])}>{s[k] ? "Turn off" : "Turn on"}</DepthButton>}
          </div>
        ))}
      </div>
    </Panel>
  );
}

export function AtlasBacklogSection() {
  const [s, setS] = useState(null);
  const [err, setErr] = useState(null);
  const [open, setOpen] = useState(null);
  const [busy, setBusy] = useState(null);
  const load = useCallback(() => { api("/api/admin/atlas-backlog").then(setS).catch(e => setErr(e.message)); }, []);
  useEffect(() => { load(); }, [load]);
  const draft = async (r) => {
    setBusy(`${r.subcategory}|${r.tech}`); setErr(null);
    try { setOpen(await api("/api/admin/atlas-backlog/draft", { method: "POST", body: JSON.stringify({ tech: r.tech, subcategory: r.subcategory }) })); load(); }
    catch (e) { setErr(e.message); } finally { setBusy(null); }
  };
  const review = async (id, status) => {
    try { await api(`/api/admin/atlas-backlog/${id}/review`, { method: "POST", body: JSON.stringify({ status }) }); setOpen(null); load(); }
    catch (e) { setErr(e.message); }
  };
  return (
    <Panel title="Rising skills → content backlog" data-admin-atlas-backlog=""
      code="D185-3: services/atlas/risingSkills.js — job_tech share of new postings (last 30 days vs the 90 before) by subcategory; atlas_backlog (migration 259) holds draft outlines."
      purpose="What the market is starting to ask for that Atlas should teach next. A draft outline is a brief for review — accepting it publishes nothing."
      numbers={s ? [[String(s.rows.length), "rising skills"], [String(s.rows.filter(r => !r.hasLesson).length), "with no lesson yet"]] : []}>
      {err && <div style={callout}>{err}</div>}
      {s && !s.rows.length && <div style={quiet}>Nothing is rising past the minimums yet ({s.minimums.recent} postings asking, {s.minimums.subcategory} new postings in the role in each window).</div>}
      {s?.rows?.length > 0 && (
        <div style={{ display: "grid", gap: 6 }}>
          {s.rows.map(r => (
            <div key={`${r.subcategory}|${r.tech}`} style={row} data-backlog-row={r.tech}>
              <b>{r.tech}</b>
              <span style={quiet}>{r.subcategoryName} · {r.baselineShare}% → {r.recentShare}% of new postings · {r.recent} asking{r.peopleHolding ? ` · ${r.peopleHolding} people hold it` : ""}{r.hasLesson ? " · has a lesson" : " · no lesson yet"}</span>
              {r.draft ? <Mark>{`outline ${r.draft.status}`}</Mark> : null}
              <DepthButton onClick={() => draft(r)} disabled={busy === `${r.subcategory}|${r.tech}`}>{r.draft ? "Redraft the outline" : "Draft an outline"}</DepthButton>
            </div>
          ))}
        </div>
      )}
      {open?.outline && (
        <div style={{ marginTop: 12 }} data-backlog-outline={open.status}>
          <div style={sub}>{open.outline.title} — draft</div>
          <div style={quiet}>{open.outline.why}</div>
          <ol>{open.outline.steps.map((x, i) => <li key={i}>{x}</li>)}</ol>
          <ul>{open.outline.sources.map(src => <li key={src.id}>{src.publisher} {src.name} — {src.use === "adapt" ? `adapt (${src.licenceClass}, with attribution)` : "link only"}</li>)}</ul>
          <div style={quiet}>{open.outline.note}</div>
          <div style={row}>
            <DepthButton onClick={() => review(open.id, "accepted")}>Accept as a brief</DepthButton>
            <DepthButton onClick={() => review(open.id, "rejected")}>Reject</DepthButton>
          </div>
        </div>
      )}
    </Panel>
  );
}

export function AtlasTab() {
  const [status, setStatus] = useState("draft");
  const [kind, setKind] = useState("");
  const [q, setQ] = useState("");
  const [rows, setRows] = useState(null);
  const [err, setErr] = useState(null);
  const [said, setSaid] = useState(null);
  const [busy, setBusy] = useState(null);
  const [open, setOpen] = useState(null);   // the slug whose editor is open (P6)

  const load = useCallback(() => {
    setErr(null);
    api(`/api/admin/atlas${status ? `?status=${status}` : ""}`).then(r => setRows(r.nodes || [])).catch(e => setErr(e.message));
  }, [status]);
  useEffect(() => { load(); }, [load]);

  const shown = useMemo(() => (rows || []).filter(r => (!kind || r.kind === kind)
    && (!q.trim() || r.name.toLowerCase().includes(q.trim().toLowerCase()))).slice(0, 200), [rows, kind, q]);

  const flip = async (r) => {
    const next = r.status === "published" ? "draft" : "published";
    setBusy(r.slug); setSaid(null);
    try {
      await api(`/api/admin/atlas/${encodeURIComponent(r.slug)}/status`, { method: "POST", body: JSON.stringify({ status: next }) });
      setSaid({ ok: true, text: `${r.name} is now ${next === "published" ? "PUBLISHED — anyone can open /atlas/" + r.slug : "a draft again — the public page is gone"}.` });
      // An unpublish by a person is recorded (it sticks); publishing again clears it — mirrored here until the next load.
      setRows(rs => (rs || []).map(x => x.slug === r.slug ? { ...x, status: next, publishedBy: next === "published" ? "you" : null,
        readiness: x.readiness ? { ...x.readiness, heldBy: next === "draft" ? "you" : null } : x.readiness } : x).filter(x => !status || x.status === status));
    } catch (e) { setSaid({ ok: false, text: e.message }); }
    finally { setBusy(null); }
  };

  const recompute = async () => {
    setBusy("stats"); setSaid(null);
    try { const r = await api("/api/admin/atlas/stats", { method: "POST" }); setSaid({ ok: true, text: `On the board recomputed — ${r.postings} active postings across ${r.nodes} nodes in ${r.ms} ms.` }); load(); }
    catch (e) { setSaid({ ok: false, text: e.message }); }
    finally { setBusy(null); }
  };

  // ⭐ P6: the dead-link checker and the Wikipedia refresh, now (both also run daily).
  const checkLinks = async () => {
    setBusy("links"); setSaid(null);
    try { const r = await api("/api/admin/atlas/links/check", { method: "POST" }); setSaid({ ok: true, text: `Links checked: ${r.checked} — ${r.ok} ok, ${r.failing} failing once, ${r.dead} dead (hidden after two failures in a row).` }); }
    catch (e) { setSaid({ ok: false, text: e.message }); }
    finally { setBusy(null); }
  };
  const refreshWiki = async () => {
    setBusy("wiki"); setSaid(null);
    try {
      const r = await api("/api/admin/atlas/wiki/refresh", { method: "POST" });
      const why = Object.entries(r.reasons || {}).map(([k, n]) => `${k} ×${n}`).join(", ");
      setSaid({ ok: !r.failed, text: `Wikipedia: ${r.fetched} of ${r.due} due summaries read${r.failed ? ` — ${r.failed} failed (${why})` : ""}${r.stoppedAt429 ? " — stopped at Wikipedia's rate limit; the rest tomorrow" : ""}.` });
    }
    catch (e) { setSaid({ ok: false, text: e.message }); }
    finally { setBusy(null); }
  };

  const runAuto = async () => {
    setBusy("auto"); setSaid(null);
    try {
      const r = await api("/api/admin/atlas/auto/run", { method: "POST" });
      // ⭐ BUG 10-31: the server's describeAutoRun line — each step's counters, and a failure named as an error.
      setSaid({ ok: !!r.ok, text: `Auto-publish: ${r.line}` });
      load();
    } catch (e) { setSaid({ ok: false, text: e.message }); }
    finally { setBusy(null); }
  };

  const askAgain = async () => {
    setBusy("ask"); setSaid(null);
    try { const r = await api("/api/admin/atlas/wiki/ask-again", { method: "POST" }); setSaid({ ok: true, text: `${r.cleared} unmatched node(s) will be asked again on the next run — press Run auto-publish now.` }); }
    catch (e) { setSaid({ ok: false, text: e.message }); }
    finally { setBusy(null); }
  };

  const counts = rows ? { total: rows.length, roles: rows.filter(r => r.kind === "role").length } : null;
  return (
    <Panel data-admin-atlas="" title="Atlas"
      purpose="The Atlas's pages. A draft publishes itself nightly once 5 active postings ask for it and it has a Wikipedia summary or a definition; each draft says what it is missing. Unpublishing here sticks — auto-publish never brings it back."
      code="D105 P4 + P6 · GET /api/admin/atlas · POST …/:slug/status · …/stats · …/nodes · …/merge · …/node/:slug (edges, resources) · …/resources/:id · …/links/check · …/wiki/refresh · public reads are published-only"
      numbers={counts ? [[counts.total, status ? `${status} nodes` : "nodes"], [counts.roles, "of them roles"]] : []}>
      <div style={{ ...row, marginBottom: 12 }}>
        <div role="group" aria-label="Status" style={row}>
          {[["draft", "Drafts"], ["published", "Published"], ["", "All"]].map(([v, l]) => (
            <DepthButton key={l} size="compact" pressed={status === v} onClick={() => setStatus(v)} data-atlas-status={v || "all"}>{l}</DepthButton>
          ))}
        </div>
        <select aria-label="Kind" value={kind} onChange={e => setKind(e.target.value)} style={field}>
          {KINDS.map(([v, l]) => <option key={l} value={v}>{l}</option>)}
        </select>
        <input aria-label="Filter by name" placeholder="Filter by name…" value={q} onChange={e => setQ(e.target.value)} style={{ ...field, flex: "1 1 180px" }} />
        <DepthButton size="compact" disabled={busy === "stats"} onClick={recompute} data-atlas-recompute="">Recompute On the board</DepthButton>
        <DepthButton size="compact" disabled={busy === "links"} onClick={checkLinks} data-atlas-check-links="">Check links now</DepthButton>
        <DepthButton size="compact" disabled={busy === "wiki"} onClick={refreshWiki} data-atlas-refresh-wiki="">Refresh Wikipedia</DepthButton>
        <DepthButton size="compact" disabled={busy === "auto"} onClick={runAuto} data-atlas-run-auto="">Run auto-publish now</DepthButton>
        <DepthButton size="compact" disabled={busy === "ask"} onClick={askAgain} data-atlas-ask-again="">Ask Wikipedia again</DepthButton>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))", gap: 10, marginBottom: 12 }}>
        <AtlasAddNode say={setSaid} onAdded={(node) => { load(); setOpen(node.slug); }} />
        <AtlasMerge say={setSaid} onMerged={(r) => { setRows(rs => (rs || []).filter(x => x.slug !== r.loser)); setOpen(o => (o === r.loser ? r.winner : o)); }} />
      </div>
      <AtlasWikiAnswers reloadKey={said} say={setSaid} />
      <AtlasDraftDefinitions say={setSaid} onChanged={load} />
      <AtlasImportContent say={(s) => { setSaid(s); if (s.ok) load(); }} />
      <LearnBeforeThisReview />
      <LearnThumbnails />
      <AtlasSources say={setSaid} />
      {said && <div role="status" style={{ ...callout(said.ok ? C.SUCCESS : C.DANGER), marginBottom: 10 }}>{said.text}</div>}
      {err && <div style={{ ...callout(C.DANGER), marginBottom: 10 }}>{err}</div>}
      {!rows ? <p style={quiet}>Loading…</p> : shown.length === 0 ? <p style={quiet}>No node matches.</p> : (
        <div style={{ display: "grid", gap: 6 }}>
          {shown.map(r => (
            <div key={r.slug} data-atlas-row={r.slug} style={{ ...sub, display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
              <span style={{ flex: "1 1 200px", fontSize: 13, color: C.INK, overflowWrap: "anywhere" }}>
                <b>{r.name}</b> <span style={quiet}>{r.kind} · {r.postings} posting{r.postings === 1 ? "" : "s"} · {r.source}</span>
                {readinessLine(r) && <span style={{ ...quiet, display: "block" }} data-atlas-readiness={r.readiness?.ready ? "ready" : "not-ready"}>{readinessLine(r)}</span>}
              </span>
              <Mark tone={r.status === "published" ? C.SUCCESS : C.INK_MUTED}>{r.status}</Mark>
              {r.status === "published" && <a href={`/atlas/${encodeURIComponent(r.slug)}`} target="_blank" rel="noopener noreferrer" style={{ fontSize: 12, color: C.ACCENT_INK }}>Open page</a>}
              <DepthButton size="compact" primary={r.status !== "published"} disabled={busy === r.slug} onClick={() => flip(r)} data-atlas-flip={r.slug}>
                {r.status === "published" ? "Unpublish" : "Publish"}
              </DepthButton>
              <DepthButton size="compact" pressed={open === r.slug} onClick={() => setOpen(o => (o === r.slug ? null : r.slug))} data-atlas-edit={r.slug}>
                {open === r.slug ? "Close" : "Edit"}
              </DepthButton>
              {open === r.slug && <AtlasNodeEditor slug={r.slug} say={setSaid} />}
            </div>
          ))}
          {(rows.length > shown.length) && <p style={quiet}>Showing {shown.length} of {rows.length} — filter to find the rest.</p>}
        </div>
      )}
    </Panel>
  );
}
